export type HomeSvgAsset = keyof typeof assets;
export type NavigationSvgAsset = "home" | "home_active" | "stats" | "profile" | "settings";

export function homeSvgXml(name: HomeSvgAsset, dark = false): string {
  return assets[name][dark ? "dark" : "light"];
}

/** Recolors the supplied navigation glyph for the active capsule while keeping its paths. */
export function navigationSvgXml(
  name: NavigationSvgAsset,
  dark: boolean,
  active: boolean,
  activeBackground: string,
  activeForeground: string,
  inactive: string,
  surface: string,
): string {
  let xml = homeSvgXml(name === "home" && active ? "home_active" : name, dark);
  const muted = dark ? "#A0AAC2" : "#66718A";
  const cutout = dark ? (name === "home" ? "#10141C" : "#161C28") : (name === "home" ? "#FFFFFF" : "#FAFAFF");
  xml = xml.split(`fill="${muted}"`).join(`fill="${active ? activeForeground : inactive}"`);
  xml = xml.split(`fill="${cutout}"`).join(`fill="${active ? activeBackground : surface}"`);
  xml = xml.split('fill="white"').join(`fill="${activeForeground}"`);
  return xml.split('fill="#7650EA"').join(`fill="${activeBackground}"`);
}
